from .repository import existing_emails, put_contact

_ROW_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row):
    if not isinstance(row, dict):
        raise ValueError("row must be an object")
    keys = set(row)
    if keys != _ROW_FIELDS:
        missing = sorted(_ROW_FIELDS - keys)
        unknown = sorted(keys - _ROW_FIELDS, key=str)
        raise ValueError(f"row must have exactly email and name; missing={missing} unknown={unknown}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("email and name must be strings")
    email = email.strip().lower()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError(f"email must contain exactly one @: {email!r}")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"email must have nonempty sides around @: {email!r}")
    if any(ch.isspace() for ch in email):
        raise ValueError(f"email must not contain whitespace: {email!r}")
    if not name:
        raise ValueError("name must be nonempty")
    return email, name

def import_contacts(connection, rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    normalized = []
    seen = set()
    for row in rows:
        email, name = _normalize_row(row)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email!r}")
        seen.add(email)
        normalized.append((email, name))
    if not normalized:
        return {"inserted": 0, "updated": 0}
    with connection:
        existing = existing_emails(connection, seen)
        for email, name in normalized:
            put_contact(connection, email, name)
    updated = len(existing)
    return {"inserted": len(normalized) - updated, "updated": updated}
